export const getListCityReportsUrl = (cityId: 'curitiba' | 'londrina' | 'maringa' | 'ponta-grossa',
    params?: ListCityReportsParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/cities/${cityId}/reports?${stringifiedParams}` : `/api/cities/${cityId}/reports`
}

